        if isinstance(v, xr.DataArray):
            val = v
        else:
            try:
                val = v[:]
                # This part is not reached if v is a float
                val = xr.DataArray(val, dims=getattr(v, 'dimensions', ()), attrs={}, name=getattr(v, 'name', var_name))
